function importCsv(filePath) {
  let content;
  try { content = readFileSync(filePath, 'utf8'); }
  catch (err) { console.error(`Failed to import: ${err.message}`); process.exit(1); }
  const rows = parseCsv(content.replace(/^\uFEFF/, ''));
  if (rows.length === 0) { console.error('CSV file is empty.'); process.exit(1); }
  const header = rows[0].map((h) => h.trim());
  const idx = (name) => header.indexOf(name);
  const idCol = idx('id'), textCol = idx('text'), doneCol = idx('done'), prioCol = idx('priority'), createdCol = idx('createdAt');
  if (idCol === -1 || textCol === -1) { console.error('CSV must contain id and text columns.'); process.exit(1); }
  const todos = readTodos();
  const seen = new Set(todos.map((t) => Number(t?.id)));
  let imported = 0, skipped = 0;
  for (const row of rows.slice(1)) {
    if (row.length === 1 && row[0] === '') continue; // blank line
    const id = Number(row[idCol]);
    const text = (row[textCol] ?? '').trim();
    if (!Number.isInteger(id) || id < 1 || !text) { skipped++; continue; }
    if (seen.has(id)) { skipped++; continue; }
    const todo = { id, text };
    const priority = prioCol >= 0 ? (row[prioCol] || 'normal') : 'normal';
    todo.priority = ['high','low','normal'].includes(priority) ? priority : 'normal';
    if (doneCol >= 0 && String(row[doneCol]).trim().toLowerCase() === 'true') todo.done = true;
    todo.createdAt = createdCol >= 0 && row[createdCol] ? row[createdCol] : new Date().toISOString();
    todos.push(todo);
    seen.add(id);
    imported++;
  }
  writeFileSync(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Imported ${imported} todo(s), skipped ${skipped} row(s).`);
}
```

