  const positional = [];
  let priority;
  let priorityProvided = false;
  let tag;
  let tagProvided = false;
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--priority') {
      priorityProvided = true;
      priority = args[++i];
    } else if (arg.startsWith('--priority=')) {
      priorityProvided = true;
      priority = arg.slice('--priority='.length);
    } else if (arg === '--tag') {
      tagProvided = true;
      tag = args[++i];
    } else if (arg.startsWith('--tag=')) {
