      tag = arg.slice('--tag='.length);
    } else {
      positional.push(arg);
    }
  }
  return {
    args,
    text: positional.join(' ').trim(),
    path: args.join(' ').trim(),
    priority,
    priorityProvided,
    tag,
    tagProvided,
  };
}

